CREATE OR REPLACE FUNCTION public.customer_balance(p_customer uuid) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result numeric; sid uuid:=public.current_store_id(); BEGIN IF sid IS NULL OR NOT public.is_staff(auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.customers WHERE id=p_customer AND store_id=sid) THEN RAISE EXCEPTION 'Customer not found'; END IF; SELECT round(coalesce((SELECT sum(p.amount/nullif(p.exchange_rate,0)) FROM public.sale_payments p JOIN public.sales s ON s.id=p.sale_id WHERE s.customer_id=p_customer AND s.store_id=sid AND public.is_account_method(p.method)),0)-coalesce((SELECT sum(amount) FROM public.customer_payments WHERE customer_id=p_customer AND store_id=sid),0)-coalesce((SELECT sum(r.amount) FROM public.refunds r JOIN public.sales s ON s.id=r.sale_id WHERE s.customer_id=p_customer AND r.store_id=sid AND public.is_account_method(r.method)),0),2) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.is_cash_method(p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT is_cash FROM public.payment_types WHERE code=p AND store_id=public.current_store_id()),false) $$;
CREATE OR REPLACE FUNCTION public.is_account_method(p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT is_account FROM public.payment_types WHERE code=p AND store_id=public.current_store_id()),false) $$;
CREATE OR REPLACE FUNCTION public.check_payment_method_known() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.payment_types WHERE code=NEW.method AND store_id=NEW.store_id) THEN RAISE EXCEPTION 'Unknown payment type for this shop'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.adjust_stock(p_product uuid,p_qty numeric,p_type text,p_note text) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result numeric; BEGIN IF NOT public.can_manage_stock(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF p_type NOT IN ('opening','purchase','adjustment','damaged','expired','return') OR p_qty IS NULL OR p_qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Invalid stock adjustment'; END IF; UPDATE public.products SET stock=stock+p_qty WHERE id=p_product AND store_id=public.current_store_id() RETURNING stock INTO result; IF NOT FOUND THEN RAISE EXCEPTION 'Product not found'; END IF; INSERT INTO public.stock_movements(product_id,type,quantity,balance_after,note,user_id) VALUES(p_product,p_type,p_qty,result,p_note,auth.uid()); RETURN result; END $$;
DO $$ DECLARE r record; d text; BEGIN FOR r IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('set_user_role','set_user_active','set_user_permission','set_staff_pin') LOOP SELECT pg_get_functiondef(r.oid) INTO d; IF position('can_manage_store_member' in d)=0 THEN d:=regexp_replace(d,'(begin|BEGIN)',E'BEGIN\n IF NOT public.can_manage_store_member(p_user) THEN RAISE EXCEPTION ''That staff member belongs to another shop''; END IF;', 'i'); EXECUTE d; END IF; END LOOP; END $$;